window.DINHNGHIA={"a": "one; used before a singular noun", "about": "on the subject of", "above": "at or to a higher place than something", "after": "later than something", "again": "one more time", "alive": "living, not dead; still existing", "am": "the form of 'be' used with 'I'", "an": "one; used before a vowel sound", "an's": "belonging to An", "and": "used to join two words or ideas", "answer": "something you say or write when someone asks a question", "answered": "past form of answer: said or wrote something back to a question", "answers": "things you say or write to reply to questions", "apartment": "a set of rooms for living in, on one floor of a building", "apartments": "sets of rooms for living in, in a building", "are": "a form of 'be' used with you, we and they", "armchair": "a comfortable chair with sides that support your arms", "ask": "to say a question to get information", "asked": "said or wrote a question; told someone you want something", "asking": "saying a question to get information", "asks": "says a question to get information", "at": "used to show a place or a time", "aunt": "the sister of your mother or father, or your uncle's wife", "auntie": "A friendly word for aunt.", "author": "A person who writes a book or article.", "back": "to the place where someone or something was before", "bad": "not good; harmful", "bag": "a container used to carry things", "bags": "containers used to carry things", "be": "to exist; used to describe someone or something", "bed": "a piece of furniture for sleeping on", "bedroom": "a room for sleeping in", "bedrooms": "rooms for sleeping in", "beds": "pieces of furniture for sleeping on", "before": "earlier than something or someone", "begin": "to start doing something, or to start happening", "behind": "at the back of something or someone", "below": "at or to a lower place than something", "between": "in the space that separates two things or people", "big": "large in size", "bigger": "larger in size than something else", "biggest": "largest in size of all", "book": "a set of printed pages that you read", "books": "sets of printed pages that you read", "bookshelf": "a shelf or piece of furniture for holding books", "bookshop": "a shop that sells books", "bookworm": "a person who loves reading books", "boring": "not interesting", "box": "a container with flat sides, used to keep things in", "boxes": "containers with flat sides, used for keeping things", "boy": "a male child or young man", "boyhood": "The time when a man was a boy.", "boys": "male children or young men", "brother": "a boy or man who has the same parents as you", "brother's": "belonging to or connected with your brother", "brotherhood": "A feeling of friendship between people.", "brothers": "plural of brother: boys or men with the same parents as you", "busy": "having a lot to do; full of people or traffic", "c": "the third letter of the English alphabet, used to label a choice", "cap": "a soft hat with a hard curved part at the front", "care": "the act of looking after someone or something", "careful": "thinking about what you do so you don't make mistakes", "carefully": "with a lot of attention so that you do not make mistakes", "careless": "Not careful.", "carelessly": "In a careless way.", "cat": "a small animal with soft fur that people keep as a pet", "cautious": "Careful to avoid danger or mistakes.", "chair": "a seat for one person, with a back and usually four legs", "chairman": "the person in charge of a meeting, committee or company", "challenge": "something new and difficult that tests your ability", "choice": "The act of choosing; something you choose.", "choose": "to pick one from several things", "chores": "Regular jobs at home, like cleaning or washing.", "chose": "past form of choose: picked one from several", "chosen": "Past participle of choose.", "classmate": "a person in the same class as you at school", "clock": "a machine on a wall or table that shows the time", "clocks": "machines that show the time, not worn on the wrist", "complete": "to finish; to fill in all the parts", "completely": "in every way; totally", "completion": "the act of finishing something", "compute": "To calculate something.", "computer": "an electronic machine for storing information and working with it", "computing": "The use or study of computers.", "correct": "right or true, without any mistakes", "correction": "A change that makes something right.", "correctly": "in a way that is right or has no mistakes", "couch": "A long comfortable seat for two or more people.", "couple": "Two people together; two or a few things.", "cousin": "the child of your aunt or uncle", "cousin's": "belonging to your cousin", "cousins": "the children of your aunt or uncle", "cover": "To put something over something else.", "d": "the fourth letter of the English alphabet, used as a label", "dad": "an informal word for father", "dad's": "belonging to your father", "daddy": "A child's word for father.", "dark": "with little light; nearly black in colour", "death": "The end of life.", "describe": "to say what someone or something is like", "description": "words that say what someone or something is like", "descriptive": "Describing something.", "desk": "a table that you sit at to read, write or work", "difficult": "not easy to do or understand", "dog": "an animal that people keep as a pet or to guard a house", "draw": "to make a picture with a pencil or pen", "drawing": "making pictures with a pencil or pen", "draws": "makes a picture with a pencil or pen", "drew": "Past form of draw.", "each": "every one of two or more people or things, seen separately", "easy": "not difficult to do or understand", "elena": "a name for a girl or woman", "elena's": "belonging to or connected with Elena", "end": "the last part of something", "enlarge": "To make something bigger.", "every": "each one of a group", "everyday": "used or happening every day", "everyone": "every person in a group or place", "everything": "all things, or all the things in a situation", "example": "something that shows what other similar things are like", "exciting": "making you feel very happy and interested", "f": "The letter F, short for 'false' in true/false exercises.", "false": "Not true or not correct.", "father": "Your male parent.", "father's": "belonging to your father", "fatherly": "Kind and caring like a father.", "finish": "To complete something or come to the end of it.", "finished": "completed or already over", "first": "Coming before all the others in time or order.", "flat": "A set of rooms for living in, on one floor of a building.", "flats": "Sets of rooms for living in, on one floor of a building.", "for": "used to show who gets something or why", "form": "A type or shape of something, such as a verb form.", "formation": "The way something is made; a shape made by nature.", "forms": "different shapes or types of a word", "front": "the part that faces forward (in front of)", "fully": "completely", "game": "an activity you play for fun, with rules", "gamer": "A person who plays computer games.", "garden": "a piece of land with flowers, trees or plants near a house", "gardener": "A person who takes care of a garden.", "gardening": "The work of growing plants in a garden.", "girl": "A female child or young woman.", "girls": "Female children or young women.", "good": "Of high quality, or pleasant and nice.", "goodness": "The quality of being good; used to show surprise.", "grandfather": "The father of your father or mother.", "grandma": "An informal word for grandmother.", "grandmother": "The mother of your father or mother.", "grandmother's": "belonging to your grandmother", "grandmothers": "more than one grandmother", "grandpa": "An informal word for grandfather.", "grandparents": "The parents of your father or mother.", "great": "Very good; or very large or important.", "ha": "A Vietnamese name, for example a girl called Ha.", "hard": "Difficult; or needing a lot of effort.", "hardly": "Almost not; almost no.", "hardworking": "Putting a lot of effort into your work.", "hat": "A thing that you wear on your head.", "hats": "Things that you wear on your head.", "help": "to make it easier for someone to do something", "helpful": "Useful, or always ready to help other people.", "here": "In, at or to this place.", "ho": "Part of the name Ho Chi Minh City, the biggest city in Viet Nam.", "hoa": "A Vietnamese girl's name.", "homework": "school work that you do at home", "house": "a building where people live", "housework": "Work you do to keep a home clean and tidy.", "i": "the word you use for yourself", "in": "inside something", "incomplete": "Not finished or not having all its parts.", "incorrect": "Not right or true; wrong.", "incorrectly": "In a way that is not right.", "instruct": "To tell someone what to do or how to do it.", "is": "a form of 'be' used with he, she and it", "it": "a word for a thing or an animal", "it's": "it is", "k": "The eleventh letter of the English alphabet.", "kitten": "A young cat.", "l": "The twelfth letter of the English alphabet.", "lamp": "A thing that gives light, often on a table.", "lamps": "Things that give light, often on tables.", "lan": "a girl's name", "lan's": "Belonging to Lan.", "large": "Big in size or amount.", "largely": "Mostly; mainly.", "last": "The one before this one, or coming after all others.", "lastly": "Used to introduce the last point or thing.", "leader": "A person who leads a group or country.", "learn": "to get new knowledge or skills", "least": "Smallest in amount; 'at least' means not less than.", "less": "To a smaller degree; not as much.", "life": "The time when someone is alive, or the way someone lives.", "light": "A thing that gives light, or the brightness from the sun or a lamp.", "lights": "Things that give light, like lamps.", "little": "small in size", "live": "to have your home in a place", "liveliness": "The quality of being full of energy and interest.", "lively": "full of life, energy and activity", "living": "used in 'living room': the room where a family sits and relaxes", "look": "to turn your eyes towards something; to seem", "looked": "past form of look: turned your eyes towards something; seemed", "looking": "the -ing form of look: turning your eyes towards something", "looks": "seems; turns the eyes towards something", "m": "short form of 'am', used after I, as in I'm", "memorable": "Special and easy to remember.", "memory": "something you remember from the past; the ability to remember", "memorise": "To learn something so that you remember it exactly.", "mi": "a girl's name", "mi's": "belonging to Mi", "model": "a person who is a good example to copy; a small copy of something", "mother": "a female parent", "motherhood": "The state of being a mother.", "motorbike": "a vehicle with two wheels and an engine", "motorbikes": "vehicles with two wheels and an engine", "mum": "an informal word for mother", "mum's": "belonging to your mother", "my": "belonging to me", "n": "the letter n of the English alphabet", "nam": "a boy's name", "nam's": "belonging to Nam, a Vietnamese boy", "name": "the word or words that a person or thing is called", "next": "coming straight after; beside (next to)", "nice": "pleasant, kind or good", "nick": "a boy's name", "noi": "part of the name Ha Noi, the capital of Viet Nam", "not": "used to make a sentence negative", "nothing": "Not anything.", "noun": "a word that names a person, place, thing or idea", "o'clock": "Used after a number to say the exact hour.", "object": "(grammar) the noun or pronoun that comes after a verb; also a thing you can see and touch.", "of": "belonging to; part of", "off": "away from a place; not working or not switched on", "on": "touching the top of something; used before days and dates", "one": "the number 1", "ones": "used instead of a plural noun to avoid repeating it", "only": "no more than; nobody or nothing else", "or": "used to show another possibility", "out": "Away from the inside of a place or thing.", "outdoor": "Happening or used outside, not in a building.", "outside": "Not in a place, or not in a building; beyond the edge of an area.", "over": "During a period of time; also more than a number.", "p": "In 'p.m.', used after a time to show it is after midday.", "pair": "Two people or things that are together.", "pairs": "Plural of pair: groups of two.", "parents'": "Belonging to the parents.", "partly": "Not completely; to some degree.", "partner": "A person you work or do an activity with.", "partnership": "A relationship in which people work together.", "pen": "A thing used for writing with ink.", "pencil": "A thing used for writing or drawing, made of wood with a black centre.", "people": "men, women and children", "person": "A man, woman or child.", "personal": "Belonging to or about one person.", "personality": "the kind of person you are; your character", "photo": "A picture made with a camera.", "photograph": "A picture made with a camera.", "photographer": "A person who takes photos, often as a job.", "photography": "The art or hobby of taking photos.", "photos": "Plural of photo: pictures made with a camera.", "pick": "To choose something, or to take fruit or flowers from a plant.", "picked": "Past tense of pick; picked up means collected someone.", "picture": "A drawing, painting or photo.", "pictures": "drawings, paintings or photos", "pillow": "a soft thing you put your head on in bed", "pillowcase": "A cloth cover for a pillow.", "place": "A particular area, building or position.", "places": "Plural of place: areas, buildings or positions.", "plural": "Showing more than one person or thing.", "position": "The place where somebody or something is.", "possess": "To have or own something.", "possession": "having or owning something", "possessive": "In grammar, showing who something belongs to.", "preposition": "A word like 'in', 'on' or 'at' used before a noun.", "prepositions": "Plural of preposition: words like 'in', 'on', 'under'.", "proper": "Right or correct.", "pupil": "A child who goes to school.", "puppy": "A young dog.", "question": "something you ask to get information", "questionnaire": "A list of questions to get information from people.", "questions": "things you ask to get information", "quiet": "Making very little noise or having little noise around.", "r": "The letter r.", "reply": "to say or write something as an answer", "right": "correct; the side opposite left", "rightly": "Correctly or fairly.", "room": "A part of a house or building with walls, a floor and a ceiling.", "said": "past tense of say", "sample": "An example that shows what something is like.", "say": "To speak words to tell someone something.", "saying": "Speaking words; also a well-known short sentence with advice.", "school": "a place where children go to learn", "schoolbag": "A bag for carrying books to school.", "seem": "To appear to be.", "select": "To choose something carefully.", "sentence": "a group of words that expresses a complete idea", "sentences": "groups of words that express complete ideas", "she": "a word for a girl or a woman", "she's": "she is", "shelf": "a flat board on a wall or in a cupboard to put things on", "shop": "a place where you buy things", "single": "Only one; or not married to anyone.", "singly": "One at a time; alone.", "singular": "showing only one person or thing", "sister": "A girl or woman who has the same parents as you.", "sister'": "Part of a possessive form of 'sister'.", "sister's": "belonging to your sister", "small": "Little in size or amount.", "sofa": "A long, soft seat for two or more people.", "something": "A thing, but you do not know or say what.", "speak": "To say words; to use a language.", "speaker": "A person who speaks; a machine that makes sound louder.", "speech": "spoken words; a talk given to a group of people", "spoke": "The past form of 'speak'.", "start": "to begin doing something or to make something begin", "student": "a person who studies at a school or university", "studies": "learns about a subject", "study": "to spend time learning about a subject", "surname": "Your family name.", "t": "the last letter of n't, the short form of 'not'", "table": "information arranged in rows and columns; a piece of furniture", "talk": "to speak to someone", "taught": "The past form of 'teach'.", "teach": "to give lessons to students; to help someone learn", "teacher": "a person whose job is to teach", "teacher's": "belonging to or used by a teacher", "teaching": "giving lessons; the job of a teacher", "televise": "To show something on television.", "television": "a machine with a screen that shows programmes", "that": "used for a thing further away; used to join ideas", "the": "used before a noun when we know which one", "their": "belonging to or connected with them", "them": "a word for people or things (after a verb)", "then": "next, after that; at that time", "there": "in or at that place; used with 'be' to say something exists", "there's": "the short form of 'there is'", "they": "a word for two or more people or things", "they're": "they are", "thing": "an object, idea or event that you do not name exactly", "things": "objects; ideas or actions", "this": "used for a thing near you", "timetable": "A list showing the times of lessons or events.", "to": "towards; used before a verb", "totally": "completely, in every way, without any exception", "true": "correct; real", "truly": "Really; sincerely.", "truth": "The real facts about something.", "tv": "A piece of equipment with a screen for watching programmes.", "twelfth": "Coming after eleven others (12th).", "twelve": "The number 12.", "two": "the number 2", "uncle": "the brother of your mother or father, or the husband of your aunt", "under": "In or to a position below something.", "untrue": "False; not true.", "use": "To do something with a thing for a purpose.", "useful": "Helping you to do or get what you want.", "usefully": "In a useful way.", "usefulness": "The quality of being useful.", "useless": "Not useful.", "user": "A person who uses something.", "v": "A short form of 'verb' used in grammar patterns.", "verb": "A word that shows an action or a state, like 'run' or 'be'.", "verbs": "Words that show actions or states, like 'run' or 'be'.", "vi": "Part of the name Ba Vi, a mountain area near Ha Noi.", "wardrobe": "A tall cupboard where you hang your clothes.", "was": "Past form of 'be' used with I, he, she, it and singular nouns.", "watch": "To look at something for some time, such as TV or a game.", "watches": "Looks at something for some time (he/she/it form).", "we": "a word for you and me together", "well": "in a good way", "were": "Past form of 'be' used with you, we, they and plural nouns.", "where": "used to ask about a place", "with": "together with; having", "without": "not having", "work": "a job; to do a job", "worker": "A person who works, especially in a factory or on a farm.", "working": "The -ing form of 'work': doing a job or an activity.", "write": "to put words on paper or a screen", "writer": "A person who writes books, stories or articles.", "writing": "The -ing form of 'write': putting words on paper or a screen.", "wrong": "not correct", "wrongly": "In a way that is not correct.", "y": "The letter Y, used in the spelling rule 'ie' to 'y' + -ing."};
window.EXAUD={"Can you say that again, please?": "audio/cau/7e3810543bbdcfd8.mp3", "Mi read the story again and again.": "audio/cau/1afa85aeab810227.mp3", "We must keep our traditional crafts alive.": "audio/cau/461c910cfd0f1264.mp3", "The old tree is still alive, but that one is dead.": "audio/cau/713514d344b69a38.mp3", "I am a student at Kim Dong School.": "audio/cau/7c9effe742362b92.mp3", "I am in Class 6A, and my friends are in 6B.": "audio/cau/69bce6abc68e1822.mp3", "Please answer the teacher's question.": "audio/cau/f790ccdd60f40ece.mp3", "Nam asks and Hoa answers.": "audio/cau/128cffcafde831b9.mp3", "Mai answered all the questions in the quiz.": "audio/cau/c93d065e33503510.mp3", "Khoa answered \"Yes\" to question 3.": "audio/cau/0f875ac2987d5d20.mp3", "Check your answers with a partner.": "audio/cau/8656910f569b2925.mp3", "Lan can answer all the questions, and her answers are correct.": "audio/cau/df2a478d26596242.mp3", "We live in an apartment on the tenth floor.": "audio/cau/4e92ae5a41f11424.mp3", "Nam's family moved to a new flat in a big apartment building.": "audio/cau/9d5250ee060002c6.mp3", "Many people in the city live in apartments.": "audio/cau/9bf724316bf72e36.mp3", "Our apartment is small, but the other apartments are bigger.": "audio/cau/4f4fbeb000424176.mp3", "Mi and Nam are in Class 6A.": "audio/cau/b0d165e52ca7dc85.mp3", "We are happy today, and Lan is happy too.": "audio/cau/9718e7702bade08e.mp3", "The dog is next to the armchair.": "audio/cau/9be1de999714b13b.mp3", "My grandfather reads books in his armchair.": "audio/cau/645c4b215c7bc50a.mp3", "You can ask your teacher for help.": "audio/cau/675c99f05fae3d5e.mp3", "Phong asked a question, and Mi answered it.": "audio/cau/ad374096f949206b.mp3", "Nam asked his teacher a question.": "audio/cau/4879a0b703b8484f.mp3", "Mi asks a lot of questions; yesterday she asked ten.": "audio/cau/1884bf7fdb16c86c.mp3", "Lan is asking her mother about dinner.": "audio/cau/28eda1c06b5eacae.mp3", "Nam asks a lot, and now he is asking again.": "audio/cau/c563c3f4819710c9.mp3", "Minh asks his friend for a pen.": "audio/cau/463760cf3bb33508.mp3", "Hoa often asks questions, and yesterday she asked ten.": "audio/cau/99ce048ae007844f.mp3", "My aunt lives in a big house in Hue.": "audio/cau/80f70063c28b771a.mp3", "My aunt and uncle visit us every Tet.": "audio/cau/12cfb3f9e75f36ef.mp3", "Auntie Lan bakes great cakes.": "audio/cau/0399f44fb6095c71.mp3", "I visit my auntie every summer.": "audio/cau/82851a56ad9bd694.mp3", "Who is the author of this book?": "audio/cau/307f149b72d48019.mp3", "To Hoai is a famous author.": "audio/cau/e04eb4b941758460.mp3", "Look at picture b and answer.": "audio/cau/b2672a8a1898ddda.mp3", "Write the letter b next to the right answer.": "audio/cau/9ec7b58bf879e0bc.mp3", "He came back to his village after the war.": "audio/cau/97697c4a9d748fa3.mp3", "Nam went to Hue and came back on Sunday.": "audio/cau/1bf8eb10f268125e.mp3", "Eating too much sugar is bad for your teeth.": "audio/cau/385b55508b3849c3.mp3", "The traffic was bad today, but yesterday it was worse.": "audio/cau/4db5861a9ee30736.mp3", "My school bag is very heavy.": "audio/cau/81c86f54e6817fa3.mp3", "Mi has a red bag, and Lan has two blue bags.": "audio/cau/33eb6b7417d04199.mp3", "Please use cloth bags instead of plastic bags.": "audio/cau/6e414fb5f6866be5.mp3", "This bag is old, so Mum bought two new bags.": "audio/cau/5c197b55387c41e0.mp3", "Please be quiet in the library.": "audio/cau/d6fab02a2655be4e.mp3", "I want to be a doctor. My sister is a nurse.": "audio/cau/e31166f3ca032296.mp3", "I go to bed at ten o'clock.": "audio/cau/37f1c2a86a0f3867.mp3", "There is a bed and a desk in my bedroom.": "audio/cau/5306adc35ff279d9.mp3", "My bedroom is small but tidy.": "audio/cau/8f6e673cf7c0e7d7.mp3", "There is a big bed in my bedroom.": "audio/cau/a25f15f6ef9e509d.mp3", "Our house has three bedrooms.": "audio/cau/56d369b001af2fce.mp3", "Each bedroom has a bed and a desk.": "audio/cau/e433eafa2f6c6dd2.mp3", "There are two beds in my room.": "audio/cau/3cc7c6e3c214f1b9.mp3", "My bed is near the window; my sister's is near the door.": "audio/cau/80b572f1725475e4.mp3", "Our lessons begin at seven o'clock.": "audio/cau/7e2700abcf553879.mp3", "The film began at 8 p.m. and finished at 10 p.m.": "audio/cau/27d24f5e96b08bae.mp3", "Our school has a big garden.": "audio/cau/6b86817f41024790.mp3", "My house is big, but Minh's house is bigger.": "audio/cau/1d7d2b8d19284673.mp3", "Ho Chi Minh City is bigger than Da Nang.": "audio/cau/5efe9fe286047142.mp3", "My house is big, but Nam's house is bigger.": "audio/cau/44f8b6366001f6da.mp3", "This is the biggest market in the city.": "audio/cau/ba6358ef44b7b295.mp3", "Ho Chi Minh City is the biggest city in Viet Nam.": "audio/cau/815c69dda42327e1.mp3", "She wrote a book about her life.": "audio/cau/428afa8d58f841a3.mp3", "Lan reads a book every week, so she has many books.": "audio/cau/5a4070779479f823.mp3", "I like reading books about animals.": "audio/cau/161e5202b70a9850.mp3", "This book is mine, and those books are Nam's.": "audio/cau/564922fbe3abbd87.mp3", "There is a bookshelf next to my bed.": "audio/cau/28c26e10a15e44bb.mp3", "We have one bookshelf in the living room and two bookshelves upstairs.": "audio/cau/1f773c2cd37855a0.mp3", "Let's meet at the bookshop at three.": "audio/cau/edd3dfa5312f3d80.mp3", "Mi buys books at the bookshop near her school.": "audio/cau/f582ec87c6413bc0.mp3", "My sister is a bookworm; she reads all day.": "audio/cau/c8db770130f6abe1.mp3", "Nam is a bookworm and has hundreds of books.": "audio/cau/8d410197b8c04d62.mp3", "The film was long and boring.": "audio/cau/2fb37c98bad76a4f.mp3", "The lesson was boring, so Nam felt bored.": "audio/cau/0b9b11807d964d8b.mp3", "There is a cat in the box.": "audio/cau/2e85eeb9526b3b0e.mp3", "Put the toys in the box; we have three boxes.": "audio/cau/94612872a7e7c8fc.mp3", "The toys are in the boxes.": "audio/cau/170d9e1f4536be5e.mp3", "Mai puts her books in two boxes.": "audio/cau/895f5119e1e2f239.mp3", "The boy next to Mi is my brother.": "audio/cau/2b8e169ba1253282.mp3", "There are ten boys and twelve girls in my class.": "audio/cau/f109fb5b9db06caa.mp3", "My dad told me about his boyhood.": "audio/cau/07bbaf2f97aea1c8.mp3", "This is his boyhood home.": "audio/cau/290020f85e6dc306.mp3", "The boys are playing football in the yard.": "audio/cau/a14f1aea2e9181df.mp3", "One boy is reading, and the other boys are drawing.": "audio/cau/4ae5ad7c214a1d49.mp3", "My brother is ten years old.": "audio/cau/8117bffc8b9c9ebf.mp3", "Lan has two brothers and one sister.": "audio/cau/2a5491a08996a7e7.mp3", "My brother's bedroom is next to mine.": "audio/cau/f1b45b215b39838f.mp3", "This is my brother, and that is my brother's bike.": "audio/cau/22273538d6265be4.mp3", "Sport brings a sense of brotherhood.": "audio/cau/60ab616f45158de4.mp3", "The festival celebrates brotherhood.": "audio/cau/7eb183fc4d55f45d.mp3", "I have two brothers and one sister.": "audio/cau/40fabe17eb0c1d6b.mp3", "Minh's brothers are tall, but his sister is short.": "audio/cau/75d0c7461a54ce03.mp3", "My mum is always busy at weekends.": "audio/cau/e860f8923617b0aa.mp3", "Hoa is busy today, but she is free tomorrow.": "audio/cau/1d5a0a62fb11072c.mp3", "The correct answer is c.": "audio/cau/115cc222c2d7fb6e.mp3", "Look at picture c and describe the girl.": "audio/cau/a211a53ea5c1cc24.mp3", "Phong is wearing a red cap.": "audio/cau/47e74bf1b6095c6b.mp3", "Mi has a cap, and her brother has a big hat.": "audio/cau/9b7781b3a4d92b59.mp3", "Old people in my village need special care.": "audio/cau/e2b32589dc4d57eb.mp3", "Lan takes care of her little brother very carefully.": "audio/cau/0449e85740a5edad.mp3", "Be careful when you cross the road.": "audio/cau/7d44eca76d25a07d.mp3", "Nam is careful, so he writes carefully.": "audio/cau/3961f897eee5f47e.mp3", "Listen carefully and repeat after me.": "audio/cau/ad3f1bf6d7562211.mp3", "Mi is careful, so she always writes carefully.": "audio/cau/6be5befe9f5467c7.mp3", "Don't be careless with fire.": "audio/cau/3fa8f5ce401f56eb.mp3", "He made a careless mistake.": "audio/cau/0e576f1b557d8217.mp3", "He drives carelessly.": "audio/cau/0042728a9cbcae0d.mp3", "She carelessly left the door open.": "audio/cau/72fb5e9acc250bb9.mp3", "There is a cat under the bed.": "audio/cau/b07c0b9bf36ecd88.mp3", "Our cat has two little kittens.": "audio/cau/faccccf3b8679bc0.mp3", "Be cautious when you cross the road.": "audio/cau/9dd111c2f2e4c687.mp3", "She is a cautious driver.": "audio/cau/b817922787a617d7.mp3", "There is a chair next to the desk.": "audio/cau/6e23e963e91d64de.mp3", "Nam sits on a chair, and Mi sits on the sofa.": "audio/cau/46f607b87b404baf.mp3", "The chairman of the city council spoke at the meeting.": "audio/cau/2f141f93b7235ff1.mp3", "He will chair the meeting as chairman.": "audio/cau/91cec725adde79d6.mp3", "Let's play a memory challenge in pairs.": "audio/cau/087734251efbe84e.mp3", "Learning new words is a fun challenge.": "audio/cau/c2202c8e65187d81.mp3", "You have a choice of tea or juice.": "audio/cau/d83c640d99d55e18.mp3", "I think you made a good choice.": "audio/cau/89c0a3eddbcb6efd.mp3", "Choose the correct answer.": "audio/cau/9bb3b69b3f099527.mp3", "Mi chose a red pen. It was a good choice.": "audio/cau/4fabb83c5ec962f5.mp3", "I help my mum with the chores.": "audio/cau/ec58d4ed18c9c760.mp3", "Doing chores is my duty at weekends.": "audio/cau/09249f9d1a1fd9c1.mp3", "I chose the bus because it is cheap.": "audio/cau/9c85ffa2fb7223db.mp3", "You can choose one, and Nam chose the red one.": "audio/cau/3684e06d8810f79f.mp3", "She was chosen as class monitor.": "audio/cau/77ca45b3c93c0c06.mp3", "Have you chosen a book yet?": "audio/cau/69586b45796a6e5b.mp3", "Nam is my new classmate.": "audio/cau/8f038868644223fc.mp3", "My classmate and I sit in the same classroom.": "audio/cau/ebc5ea3d6e23a8ba.mp3", "There is a clock on the wall.": "audio/cau/db00df18f8f94a24.mp3", "Nam has a watch, but his room has no clock.": "audio/cau/93f2ef3a8ab5efe7.mp3", "There are two clocks in my house.": "audio/cau/a9d6378a171f6866.mp3", "The clocks on the wall are old.": "audio/cau/652206fdc37e4c8c.mp3", "Complete the sentences with the words.": "audio/cau/a10abe8427f587a5.mp3", "Mi completed her homework. Now it is complete.": "audio/cau/e89d49e3a54806e8.mp3", "Lan completely forgot her friend's birthday.": "audio/cau/ae968fd2ecb01b87.mp3", "Minh completely forgot about his homework.": "audio/cau/4ec9cda7a9209eb1.mp3", "Nam plans his time well to ensure timely completion of his project.": "audio/cau/dc9f46bca5bd24cf.mp3", "After the completion of the test, Hoa felt relaxed.": "audio/cau/8159d955f47b0ba3.mp3", "Can you compute the total cost?": "audio/cau/a8d41aba6d2ab55f.mp3", "Machines can compute very fast.": "audio/cau/72c349cdf691477f.mp3", "He bought his first computer at sixteen.": "audio/cau/89b36254c871cb46.mp3", "She studied computing and now makes computer games.": "audio/cau/bc002ad22303f977.mp3", "Computing is my favourite subject.": "audio/cau/bd53d2b166706315.mp3", "She wants to study computing at university.": "audio/cau/dc25a1b43d7542f9.mp3", "Choose the correct answer A, B or C.": "audio/cau/6f45c31e9ee537be.mp3", "Nam's answer is correct, but mine is wrong.": "audio/cau/2f88ef38a2385ee5.mp3", "The teacher made corrections in red.": "audio/cau/895634813fdf81d2.mp3", "Check your corrections carefully.": "audio/cau/c829f7ab4f978d5b.mp3", "Try to say these new words correctly.": "audio/cau/d4da04af4337ec0f.mp3", "Her answer is correct because she read the question correctly.": "audio/cau/cee1de65a2a9d88f.mp3", "Dad is sleeping on the couch.": "audio/cau/121491e14320d1f2.mp3", "Don't be a couch potato!": "audio/cau/2b34fa82077244b4.mp3", "A young couple lives next door.": "audio/cau/d0f20b42a6aca611.mp3", "Wait a couple of minutes.": "audio/cau/88b6985e0d22ec59.mp3", "My cousin Lan lives in Hue.": "audio/cau/309e0790230bcfd2.mp3", "Nam has three cousins, and his cousin Minh is twelve.": "audio/cau/4f935c8501597824.mp3", "My cousin's dad is my uncle.": "audio/cau/b03de28fcaabc62f.mp3", "My cousin's house is in Da Nang.": "audio/cau/8a7a2ca32134a5e5.mp3", "I often play with my cousins at Tet.": "audio/cau/d45079ad345fc4a0.mp3", "Lan has five cousins in Da Nang.": "audio/cau/7382ebeafc5e0168.mp3", "Cover your mouth when you sneeze.": "audio/cau/934dfc9e949736c3.mp3", "Snow covers the mountains.": "audio/cau/f26f2d71f0fe425d.mp3", "Look at picture d and answer the question.": "audio/cau/cd1db823a64876e3.mp3", "Choose answer d, then write it in your notebook.": "audio/cau/d8924058670ef40e.mp3", "My dad is a doctor.": "audio/cau/87de43de098d8ab6.mp3", "My dad cooks dinner, and my mum washes the dishes.": "audio/cau/8ca0dad82745ad96.mp3", "My dad's bike is next to the door.": "audio/cau/4cbed6621cec4398.mp3", "My dad's car is in the garage.": "audio/cau/7248ca58c07c9946.mp3", "Daddy, can you read me a story?": "audio/cau/7b9c274b06183fb5.mp3", "My daddy works in a hospital.": "audio/cau/7cb12862406fc83e.mp3", "It is dark outside now.": "audio/cau/48eaca11c1014cbe.mp3", "Minh's room is dark, so he turns on the light.": "audio/cau/8c6105f992faba73.mp3", "The death of his dog made him sad.": "audio/cau/16557e1350bb02d1.mp3", "Smoking can cause death.": "audio/cau/e5da19be59040040.mp3", "Can you describe your house?": "audio/cau/a0d5ad73f19e51bc.mp3", "Describe your friend and read your description to the class.": "audio/cau/5e8b000dcde9e11f.mp3", "Write a short description of your friend.": "audio/cau/1d3f9d3cf060662c.mp3", "Phong describes his school, and his description is funny.": "audio/cau/9801d95651b1cda6.mp3", "Write a descriptive paragraph about your room.": "audio/cau/053c0911268b28bb.mp3", "Use descriptive words like 'tall' and 'kind'.": "audio/cau/05df1ce0b4bb46d0.mp3", "My desk is next to the window.": "audio/cau/e8ec7e6d606e8c39.mp3", "Each student has a desk, so we have forty desks.": "audio/cau/53254f045d6e0dc6.mp3", "Maths is difficult for me.": "audio/cau/16bb57fb47e5df02.mp3", "This test is difficult, but that one is easy.": "audio/cau/56b22511f0d64b7c.mp3", "I have a small dog.": "audio/cau/d418efa45ea78edf.mp3", "Our dog plays with our neighbour's puppy.": "audio/cau/fe69c388bd55c243.mp3", "Can you draw a cat?": "audio/cau/be2932fbc93e80e5.mp3", "Hoa drew a flower and gave me the drawing.": "audio/cau/8ef26c64079b1115.mp3", "Lan's drawing is on the wall.": "audio/cau/e1c99913c9bb1dcf.mp3", "Minh draws well. He drew this drawing yesterday.": "audio/cau/a06a821e60587e14.mp3", "My brother draws pictures of animals.": "audio/cau/f72f002c0ce9c3b5.mp3", "Mi draws every day, and last week she drew a horse.": "audio/cau/c53f78fbfbf3ff78.mp3", "He drew a cat on the board.": "audio/cau/60aeb1a679f13bef.mp3", "We drew pictures in the art lesson.": "audio/cau/cffb3f0aaad7fa4f.mp3", "This English exercise is very easy.": "audio/cau/708befc5d340e6e4.mp3", "This question is easy, but that one is difficult.": "audio/cau/6ec1dbc0277d41ef.mp3", "At the end of the story, he became a hero.": "audio/cau/4cef74a2fd4fb11a.mp3", "We read to the end, and the ending was happy.": "audio/cau/fc827bfa0e26aa94.mp3", "Can you enlarge this photo?": "audio/cau/f7ea9d85d2ae68b7.mp3", "They plan to enlarge the school library.": "audio/cau/98d58917fdd12ccd.mp3", "Cooking is an everyday activity for my mum.": "audio/cau/03801a514b91f476.mp3", "We use everyday English every day at school.": "audio/cau/61f0eab70fe5dd6e.mp3", "Look at the example first.": "audio/cau/738e63739d26fe10.mp3", "Give an example; for example, cat is a noun.": "audio/cau/dc9ac2f421dfc6ef.mp3", "City life is exciting for teens.": "audio/cau/28945e456a70e4ca.mp3", "The trip was exciting, so we were very excited.": "audio/cau/53c60dbfd0e789cf.mp3", "Write T for true or F for false.": "audio/cau/d086c486993b428b.mp3", "Sentence 2 is false, so Nam writes F.": "audio/cau/87a27d221b2ce0ec.mp3", "Is this sentence true or false?": "audio/cau/b08a12186b6dfb5e.mp3", "That answer is false, but Hoa's answer is true.": "audio/cau/493842939182df2a.mp3", "My father is a doctor in Ha Noi.": "audio/cau/ad3b88cec9d38c40.mp3", "Hoa's father and grandfather are both farmers.": "audio/cau/86e9c9df994f954c.mp3", "My father's motorbike is in the garden.": "audio/cau/031e06b3d057f56e.mp3", "My father's room is next to the kitchen.": "audio/cau/d5886977bb2adf27.mp3", "The teacher gave me fatherly advice.": "audio/cau/1c51ba3a66a1d34d.mp3", "He has a fatherly smile.": "audio/cau/841699212759aa15.mp3", "I finish my homework before dinner.": "audio/cau/4c12023029931700.mp3", "Hoa started the project in May and finished it in June.": "audio/cau/92423d5fe3d5c777.mp3", "Use the past simple for finished events.": "audio/cau/15e768d53722862d.mp3", "We finished our visual story yesterday.": "audio/cau/da44bbf9abdec66f.mp3", "We live in a flat in the city centre.": "audio/cau/d0952d39ace4e187.mp3", "Mi's flat is small, but it has a nice balcony.": "audio/cau/5bb5801d0d7e1e94.mp3", "In my future city, people live in smart flats.": "audio/cau/2647fcaf50d15541.mp3", "My aunt lives in a flat in a block of flats.": "audio/cau/edb1d75dbb47094e.mp3", "Write the correct form of the verb.": "audio/cau/704fc6fb85cc3f27.mp3", "'Going' is the -ing form of 'go'.": "audio/cau/8b6c34b2f8dd653a.mp3", "The cave has amazing rock formations.": "audio/cau/044cef15503b6f02.mp3", "We learnt about the formation of rain.": "audio/cau/69ef9163d5895073.mp3", "Complete the sentences with the possessive forms.": "audio/cau/515af86bc30e1e15.mp3", "Learn the plural forms of these nouns.": "audio/cau/5c7ac5af30900826.mp3", "There is a big tree in front of our school.": "audio/cau/d5c5b9fac049ab02.mp3", "Minh sits at the front, and Lan sits at the back.": "audio/cau/945e3d0c24f5a57e.mp3", "After a good sleep, Lan is fully alert in class.": "audio/cau/e731cef6fdf5dd54.mp3", "Minh hasn't fully recovered from his cold.": "audio/cau/8cd54850c26f30ee.mp3", "The word 'garden' starts with the letter G.": "audio/cau/855344adad6266b6.mp3", "Please write a capital G on the board.": "audio/cau/090b2d929a80461a.mp3", "We play a game in our English class.": "audio/cau/f89d92956bddd8c5.mp3", "My brother is a gamer, and he loves this game.": "audio/cau/5869b678fdd00fcc.mp3", "My brother is a serious gamer.": "audio/cau/7a29eee205c35813.mp3", "Gamers should take breaks to rest their eyes.": "audio/cau/714192b94227026f.mp3", "My grandmother has a small garden.": "audio/cau/ad0b9ba5604dc0f5.mp3", "Grandpa loves gardening, so our garden is beautiful.": "audio/cau/2afdcb2a5601fa6f.mp3", "The gardener waters the flowers every day.": "audio/cau/22a67e0a027f6f3e.mp3", "My grandpa is a good gardener.": "audio/cau/ab1e7c940217b2ba.mp3", "My grandpa enjoys gardening in his free time.": "audio/cau/fcd49413f27e2295.mp3", "Gardening is fun, and our garden looks beautiful.": "audio/cau/59d0b9e54bc0416e.mp3", "The girl in the red dress is my sister.": "audio/cau/5c0a090c7edf82c5.mp3", "There are fifteen girls and twenty boys in my class.": "audio/cau/6f902e1712b320f2.mp3", "The girls are playing badminton.": "audio/cau/52ee8ca04fd9a936.mp3", "One girl wears glasses, and the other girls don't.": "audio/cau/b79f88c94a17e5cf.mp3", "Nam is good at maths.": "audio/cau/4fd3587c745c05a2.mp3", "Lan's English is good, but Mi's is better.": "audio/cau/d371c25a8502dc92.mp3", "My goodness! It's so hot today.": "audio/cau/262b2c15cb0e80ce.mp3", "She helped us out of goodness.": "audio/cau/68406886afe46623.mp3", "My grandfather is 75 years old.": "audio/cau/aaac8af2aea80407.mp3", "My grandfather and grandmother live in Hue.": "audio/cau/a198eed6e615b9c6.mp3", "My grandma tells us stories every night.": "audio/cau/96809300e183923c.mp3", "Grandma and Grandpa live with us.": "audio/cau/8051252f03d98b36.mp3", "My grandmother makes conical hats by hand.": "audio/cau/fb6599cb79d9916d.mp3", "Lan calls her grandmother 'Grandma'.": "audio/cau/61992d8dfda62651.mp3", "My grandmother's house is in Ha Noi.": "audio/cau/81ddc82bc7ef30bc.mp3", "My grandmother's garden is very big.": "audio/cau/b37f095b956fb866.mp3", "I have two grandmothers.": "audio/cau/9ebf47e8b202dc96.mp3", "My grandmothers live in the countryside.": "audio/cau/dfec03e53bd7922e.mp3", "Grandpa is reading the newspaper.": "audio/cau/d2d844236b1f3b5a.mp3", "Grandpa is my mum's father, and he is very kind.": "audio/cau/5f39a7c7669e2379.mp3", "My grandparents live in the countryside.": "audio/cau/14d9858e971da542.mp3", "Minh visits his grandparents; his grandfather has a farm.": "audio/cau/ff809b7d116e870e.mp3", "That's a great idea for our project!": "audio/cau/a54aafc7aa505f92.mp3", "We had a great time; the trip was wonderful.": "audio/cau/3dc3e9c44a5960ce.mp3", "The maths test was very hard.": "audio/cau/0fd61471858155e3.mp3", "Minh works hard; he is a hardworking student.": "audio/cau/32c549e4a9f6fc13.mp3", "I could hardly hear the teacher.": "audio/cau/144fb5f35860f6c9.mp3", "He hardly ever eats vegetables.": "audio/cau/2dbec027597d3ff1.mp3", "Lan is a hardworking student.": "audio/cau/5b3ff11d5293f4e5.mp3", "Nam is hardworking, and he never gets lazy.": "audio/cau/06cd2484f9437f49.mp3", "My grandmother makes a conical hat every day.": "audio/cau/785403050e59025d.mp3", "Lan wears a hat, and her brother has two hats.": "audio/cau/4a6004eb3f79a96b.mp3", "Chuong village is famous for its conical hats.": "audio/cau/6dfed07c1faf710a.mp3", "Each hat is made from goi leaves.": "audio/cau/d340f8c644be6611.mp3", "Can you help me with my homework?": "audio/cau/59064ec1f34486d3.mp3", "Mi is helpful; she always helps her mum cook.": "audio/cau/82b6e08d58022ab1.mp3", "The map is very helpful for tourists.": "audio/cau/01dfa6b6d0d2dc96.mp3", "Mi is helpful; she often helps her neighbours.": "audio/cau/28366edc55c3b71c.mp3", "My bedroom is here, next to the kitchen.": "audio/cau/38f5476965ee13ae.mp3", "Come here, Nam! Your bag is over there.": "audio/cau/1518838d605d3769.mp3", "I do my homework after dinner.": "audio/cau/dfa2558950305f83.mp3", "Nam does his homework at home every evening.": "audio/cau/0c529025b7e7c4aa.mp3", "Our house is near the river.": "audio/cau/462620c6e9d42610.mp3", "Lan's house is big, so the housework takes a long time.": "audio/cau/ffae3b516fc16794.mp3", "Lan helps her mother with the housework.": "audio/cau/603758dd29202743.mp3", "I do housework at weekends, like cleaning the house.": "audio/cau/603861c40de6e77e.mp3", "Your homework is incomplete.": "audio/cau/1def1df8007e7413.mp3", "Complete the incomplete sentences.": "audio/cau/865265a2ff56d7b1.mp3", "Correct the incorrect sentences.": "audio/cau/0fa204f88cc856c0.mp3", "Your answer is incorrect, so please correct it.": "audio/cau/2d6a22f249708653.mp3", "He spelled my name incorrectly.": "audio/cau/6f22f1fabc9ff68f.mp3", "If you answer incorrectly, try again.": "audio/cau/8a143b786c81fbef.mp3", "The coach instructs us how to swim.": "audio/cau/ebed61ab0a9121f1.mp3", "The teacher instructed us to sit down.": "audio/cau/2d5b2e8f5081ce26.mp3", "My school is big and beautiful.": "audio/cau/d5765e25cafa0eea.mp3", "Today it is sunny, but yesterday it was rainy.": "audio/cau/ed1bcaf6501bfd0c.mp3", "The word 'kitchen' starts with the letter k.": "audio/cau/ac85fdd0f3c32f82.mp3", "Please write a capital K on the board.": "audio/cau/f5d61da2bd65aeef.mp3", "Our cat has three kittens.": "audio/cau/d7438ba330ccfbce.mp3", "The kitten is playing with a ball.": "audio/cau/bd37be5a6206990f.mp3", "The word 'lamp' starts with the letter l.": "audio/cau/c5e08a5413a4f66b.mp3", "Please write a capital L on the board.": "audio/cau/63173cda63a08912.mp3", "There is a lamp on my desk.": "audio/cau/80d55c1669ed8758.mp3", "Turn on the lamp; the light is too weak.": "audio/cau/19093375e9e548a3.mp3", "There are two lamps in the living room.": "audio/cau/5fcc206b466bdcc2.mp3", "Mi's lamp is next to her bed.": "audio/cau/3e879c1b867d2607.mp3", "My house has a large garden.": "audio/cau/aca5eaaef305eea5.mp3", "Their house is large, and their garden is very big.": "audio/cau/58f11bb60767bcfb.mp3", "The town is largely quiet at night.": "audio/cau/6acff2f7d5971d4e.mp3", "Our success is largely due to teamwork.": "audio/cau/f39589c55d704f4b.mp3", "I visited my grandparents last weekend.": "audio/cau/553e8bea75bbdbbd.mp3", "Last Sunday was fun, and next Sunday will be fun too.": "audio/cau/17be93822cc3c397.mp3", "Lastly, turn off the lights.": "audio/cau/317a43523f160ba8.mp3", "Lastly, I want to thank my teachers.": "audio/cau/ed0db063c09f784e.mp3", "Nam is our group leader.": "audio/cau/acd4b50b90da480f.mp3", "A good leader listens to others.": "audio/cau/ebe8dd83ec209504.mp3", "We learn English at school.": "audio/cau/9bc26f3d76057248.mp3", "Nam wants to learn to swim, and his sister learnt last year.": "audio/cau/5a7392296080d626.mp3", "Students need to sleep at least eight hours a day.": "audio/cau/06d7a5fd2aadd1a8.mp3", "Nam has less homework than Mi, and Lan has the least.": "audio/cau/144df5d8b5b5a253.mp3", "Village life is less noisy than city life.": "audio/cau/00a225b39b028bcc.mp3", "I have little time, less than Mi; Nam has the least.": "audio/cau/310826397361a2bd.mp3", "He had a difficult life when he was young.": "audio/cau/0e2c7b87c896e8b7.mp3", "City life is busy, and people live very fast.": "audio/cau/c7a56b97906b19d2.mp3", "Stop when the traffic light is red.": "audio/cau/dd4921089bcbaa08.mp3", "Turn on the light, please; the room is dark.": "audio/cau/dd20920a13027c13.mp3", "There are two lights in my bedroom.": "audio/cau/5a921adf4b12e15d.mp3", "Please turn off the light when you leave.": "audio/cau/1425d60d9ad208b9.mp3", "My little brother is five years old.": "audio/cau/e22af4e6bb3d77f0.mp3", "I have a little money, but my sister has less.": "audio/cau/520fdc680c743ed9.mp3", "We live in a small village.": "audio/cau/8438d091662da029.mp3", "My grandparents live in the countryside and have a happy life.": "audio/cau/a21ec63c6b42bc8d.mp3", "The liveliness of the market surprised the tourists.": "audio/cau/1f8d1f8c4032f05b.mp3", "I love the liveliness of Tet holiday.": "audio/cau/052386f3749c3787.mp3", "Ho Chi Minh City is very lively at night.": "audio/cau/f7f9de50246fc30a.mp3", "The market is lively and busy in the morning.": "audio/cau/be87297ba2d5a7fc.mp3", "There is a big sofa in the living room.": "audio/cau/85ee341c5ccef3a3.mp3", "We live in a small house with a nice living room.": "audio/cau/a4537e161135cc8a.mp3", "Look at the board, please.": "audio/cau/512572a71fea8cfe.mp3", "Look at Minh! He is very good-looking today.": "audio/cau/3a8f3a88e8a3813b.mp3", "Nam looked at the old photos of his village.": "audio/cau/57a1a25de6c14b73.mp3", "She looked tired yesterday, but today she looks happy.": "audio/cau/72e5fb4099eea871.mp3", "Mi is looking for her notebook in the bedroom.": "audio/cau/9cf0853b1a840504.mp3", "Look! Nam is looking at the picture on the wall.": "audio/cau/debf12a72a75e3eb.mp3", "Mi looks happy today.": "audio/cau/d53ae1b2afc27fcb.mp3", "Look at Nam; he looks tired.": "audio/cau/b6b16cdb7526bf98.mp3", "I'm a student at Nguyen Du High School.": "audio/cau/fc4e40becc452649.mp3", "I'm happy because I am with my best friends.": "audio/cau/70dc61c954d001ef.mp3", "Our trip to Sa Pa was memorable.": "audio/cau/2c79f7d2441c2bf7.mp3", "It was a memorable birthday.": "audio/cau/d715b0a40f5c458c.mp3", "I have a happy memory of my grandparents' village.": "audio/cau/880af41271ddaca7.mp3", "The trip was memorable, and it is still a sweet memory.": "audio/cau/f4338fb0434f9415.mp3", "I memorise ten new words every day.": "audio/cau/c5411b9c0f960ca3.mp3", "Can you memorise this poem?": "audio/cau/64c0243e29f9cba0.mp3", "Read the model story first.": "audio/cau/96d5d11b4bc02327.mp3", "My father is my role model.": "audio/cau/d6cd0d28b863f1d8.mp3", "My mother is a nurse.": "audio/cau/7504a7ce3f463355.mp3", "Mi's mother, her mum, cooks very well.": "audio/cau/4860342249a4a0b1.mp3", "Motherhood is a wonderful job.": "audio/cau/a41df636f68c1eb3.mp3", "She enjoys motherhood very much.": "audio/cau/aae8c60a567bd35c.mp3", "My dad rides a motorbike to work.": "audio/cau/4f501015f855a570.mp3", "My motorbike is red, and there are many motorbikes in Ha Noi.": "audio/cau/66b4bec125f86be5.mp3", "There are too many motorbikes on the streets.": "audio/cau/169169b323d4e01a.mp3", "My family has one motorbike, but my uncle has two motorbikes.": "audio/cau/bea26d010d5b3eb3.mp3", "My mum works in a hospital.": "audio/cau/6797efc1f7e404e7.mp3", "I love my mum; she is a kind mother.": "audio/cau/9c8b3cd7b9c8ebfc.mp3", "My mum's hometown is a craft village.": "audio/cau/4fe16a1d11c666c0.mp3", "This is my mum's bag; my mum is a teacher.": "audio/cau/b40e69ab10d68b71.mp3", "In 'running', we double the letter n.": "audio/cau/f2d3227ba2e63feb.mp3", "Run ends in n, so we write running with two n's.": "audio/cau/840a0ecac7ac2b05.mp3", "What is your full name?": "audio/cau/3560e14e0864aa5c.mp3", "Name two products Jobs introduced after 1997.": "audio/cau/2fa79a695478cb53.mp3", "See you next week!": "audio/cau/e955abbc627cb84b.mp3", "Last week we had a test, and next week we have a trip.": "audio/cau/e51bba1694cc9fe2.mp3", "Nice to meet you, Mai.": "audio/cau/7c4c4da145e9a59d.mp3", "Lan is nice, and she always speaks nicely.": "audio/cau/b93deacf2eeac62d.mp3", "She did not give up her dream.": "audio/cau/b5d39e3052bc5fbb.mp3", "I am not tired, and I'm not hungry.": "audio/cau/9485504d93b05a38.mp3", "'Happiness' is a noun.": "audio/cau/13800fcab138059c.mp3", "A noun names a thing; 'teacher' is a noun.": "audio/cau/34772bd9ef9e3e2f.mp3", "School starts at seven o'clock.": "audio/cau/48b40b20309af08c.mp3", "The verb 'do' needs an object.": "audio/cau/39d543adf72c24e9.mp3", "In 'I love music', 'music' is the object.": "audio/cau/695391fd78ce8c91.mp3", "Turn off the lights when you leave.": "audio/cau/3a68f3ab6e248006.mp3", "Turn on the fan, but turn off the TV.": "audio/cau/bdd957c99adde5f0.mp3", "There is only one bed in my bedroom.": "audio/cau/000e91b12face3a4.mp3", "Lan is an only child; she has just one cousin.": "audio/cau/b6ec9a93c21bdf30.mp3", "Mi went out with her friends last night.": "audio/cau/6662db3eac9ce4e0.mp3", "Nam wants to find out more about his grandfather's life.": "audio/cau/c2c4b3120ecb6468.mp3", "The city has many outdoor markets.": "audio/cau/70f031e665dcb6a3.mp3", "Phong likes outdoor sports, so he often plays outdoors.": "audio/cau/62d7cb3e1f835b37.mp3", "The film starts at 8 p.m.": "audio/cau/5b3d11f7cb5bec98.mp3", "School finishes at 4.30 p.m., and I have dinner at 7 p.m.": "audio/cau/6193e0ae396e4d78.mp3", "I need a new pair of shoes for school.": "audio/cau/250c1c4ccfb0d448.mp3", "Find a partner and work in pairs.": "audio/cau/9f9cc8d6f86e7886.mp3", "Work in pairs and ask each other questions.": "audio/cau/2bae203d74ef1339.mp3", "There are ten pairs, so each pair gets one card.": "audio/cau/6a0e4948c63a816b.mp3", "This is my parents' room.": "audio/cau/bdfd9116a79179f4.mp3", "I listen to my parents' advice.": "audio/cau/e362e871fe708e0d.mp3", "It will be partly cloudy tomorrow.": "audio/cau/2e9279ced890cd59.mp3", "The story is partly true.": "audio/cau/a56a321d8dcb3386.mp3", "Ask your partner about his favourite food.": "audio/cau/422fdd4d69934397.mp3", "Minh is my partner, and we work in pairs.": "audio/cau/c79cf650c67747ae.mp3", "Our school has a partnership with a school in Japan.": "audio/cau/94480f1a5b1a2bf9.mp3", "Good partnership makes good results.": "audio/cau/6f55e8eb690f4709.mp3", "Can I borrow your pen, please?": "audio/cau/219492b77e8bce23.mp3", "Write in pen, not in pencil.": "audio/cau/61e51310622e9a99.mp3", "I draw a picture with my pencil.": "audio/cau/ecf39c9e499950e3.mp3", "Put your pen and pencil in your pencil case.": "audio/cau/cebdbe1b42b4a461.mp3", "There are five people in my family.": "audio/cau/61d24a117613907d.mp3", "One person is late, but the other people are here.": "audio/cau/b4e5b7ba18b09096.mp3", "He is a kind and hard-working person.": "audio/cau/a7cc8ccdfee48d42.mp3", "One person came first, then many people came.": "audio/cau/e2f7a3bc001f7fc0.mp3", "This is my personal diary.": "audio/cau/4bb512632de09306.mp3", "Don't share personal information online.": "audio/cau/e4de8d484708e9e5.mp3", "Hoa has a friendly personality.": "audio/cau/5e968c0ca289e9bb.mp3", "Minh has a strong character and a kind personality.": "audio/cau/e35df7bcc2cd6179.mp3", "Can you take a photo of us?": "audio/cau/4e7337681afc841a.mp3", "This photo is a nice picture of my class.": "audio/cau/94f608c9dc656d2b.mp3", "This is a photograph of my family.": "audio/cau/be34afde07857706.mp3", "She took a photograph of the sea.": "audio/cau/0deaad3e91e725aa.mp3", "My uncle is a photographer.": "audio/cau/84945e0c05f98e38.mp3", "The photographer took many pictures.": "audio/cau/78c35f6d244bab0b.mp3", "Photography is my hobby.": "audio/cau/88fd201b0df30c9f.mp3", "She joined a photography club.": "audio/cau/2a930abea3fb3545.mp3", "Look at the photos of my friends.": "audio/cau/8a988a56d17dddc5.mp3", "Mi takes a photo, and Lan takes many photos.": "audio/cau/df1811e9acc25b9a.mp3", "Pick a card, please.": "audio/cau/1e4e9d51e347aede.mp3", "We pick tea leaves in the morning.": "audio/cau/c487a2bfd0d8d890.mp3", "My uncle picked us up at the bus station.": "audio/cau/b0c8e2d47baf7115.mp3", "Lan picked some flowers in the garden.": "audio/cau/ce45c98795b6b9e7.mp3", "Look at the picture and describe the man.": "audio/cau/b1d73989f1f7619c.mp3", "Hoa draws a picture, and Nam takes a photo of it.": "audio/cau/40c2b9c3207a7713.mp3", "Mi draws beautiful pictures in art class.": "audio/cau/1037e2e30ff7fb85.mp3", "We took many photos and put the pictures on the wall.": "audio/cau/5ddc63bf192b9304.mp3", "The cap is on the pillow.": "audio/cau/492527bff7ffbc69.mp3", "My pillow is soft and white.": "audio/cau/7d27f6d6a5447aed.mp3", "I changed my pillowcase today.": "audio/cau/37fdf601d169a5b0.mp3", "The pillowcase is blue.": "audio/cau/56630e71834ae576.mp3", "This is a nice place to live.": "audio/cau/160e9180eaed0aee.mp3", "Let's meet at the usual place after school.": "audio/cau/f760c0b8e65d51b8.mp3", "There are many interesting places in my town.": "audio/cau/22530fda716b27a9.mp3", "The market is my favourite place in town.": "audio/cau/6904ef4273568097.mp3", "'Books' is a plural noun.": "audio/cau/1de619dd107bf325.mp3", "'Cat' is singular, and 'cats' is plural.": "audio/cau/7002ade4857cb70d.mp3", "Move the desk to a new position.": "audio/cau/53dbeaa57e92a7c8.mp3", "What position do you play in football?": "audio/cau/5b168c5a857dd2f5.mp3", "He possesses a large house.": "audio/cau/54bcdee1ea557095.mp3", "She possesses great skills.": "audio/cau/c409725ae9c78b75.mp3", "The 's in Mi's room shows possession.": "audio/cau/49b86fe5b7d202bc.mp3", "In \"Mi's twelve\", 's means is, not possession.": "audio/cau/e1dc95ca8f6e48b0.mp3", "We use the possessive case to show who owns something.": "audio/cau/31a8b5ffb7761ab4.mp3", "'Lan's' is the possessive form of 'Lan'.": "audio/cau/c731266135d2bafd.mp3", "'In' is a preposition of place.": "audio/cau/bb154a2344d58f0d.mp3", "Choose the correct preposition: in, on or at.": "audio/cau/1b19a4920a380909.mp3", "We learn prepositions of place in this unit.": "audio/cau/76df274700c4a28d.mp3", "'Under' is a preposition, and 'next to' is too.": "audio/cau/95839e82e1cb3684.mp3", "Wear proper shoes for running.": "audio/cau/905aea5f35a5595b.mp3", "Eat a proper breakfast.": "audio/cau/8edde44b7d4fc213.mp3", "There are 40 pupils in my class.": "audio/cau/fa147b5c3216f8cc.mp3", "She is a good pupil.": "audio/cau/e17bb8917e55a7f5.mp3", "I got a puppy for my birthday.": "audio/cau/0f9410e8f7c95b14.mp3", "The puppy is playing with a ball.": "audio/cau/9d756468bb5546bd.mp3", "Can I ask you a question, Ms Hoa?": "audio/cau/7e99e348210556f2.mp3", "Nam asks a question, and Mi gives the answer.": "audio/cau/269c53bfb0db8e6f.mp3", "Please fill in the questionnaire.": "audio/cau/a95121e3928b213d.mp3", "We did a questionnaire about hobbies.": "audio/cau/c390090db32f59d5.mp3", "The teacher asks us three questions.": "audio/cau/9e7c27a7a37e13a0.mp3", "Read the questions carefully and write your answers.": "audio/cau/7fcc03272c2a6124.mp3", "The library is a quiet place.": "audio/cau/cf5d391e8e881e58.mp3", "My village is quieter and more peaceful than the city.": "audio/cau/fe9afae0f73f7b97.mp3", "The word 'red' starts with the letter r.": "audio/cau/19d12f34975f740f.mp3", "'Rabbit' and 'room' both begin with R.": "audio/cau/aca28cd4f322eeb4.mp3", "How does Elena reply to her mum?": "audio/cau/dcaf59d7091175e8.mp3", "Please reply to my email soon.": "audio/cau/1fbb259adb0f0a8b.mp3", "Your answer is right, Nam.": "audio/cau/de0207c9ebd60141.mp3", "Is this answer right or wrong?": "audio/cau/6f5632fc348cdcbc.mp3", "She rightly said no.": "audio/cau/0716d99ea752c0a9.mp3", "He was rightly proud of his work.": "audio/cau/82f83dc7701970f6.mp3", "My room is small but very tidy.": "audio/cau/bd9658dea75a069a.mp3", "There are five rooms in my house.": "audio/cau/a28138f93ee20867.mp3", "She's my best friend in class 6A.": "audio/cau/810592fcf73e04e7.mp3", "This is Vinh's bike, and he's in my class.": "audio/cau/6a8b8131a5222edf.mp3", "I said, can you pass me the book?": "audio/cau/e2db7c41d720581d.mp3", "The teacher said we should sleep early.": "audio/cau/f9528b768b823292.mp3", "Read the sample answer before you write.": "audio/cau/ea7645ef6a324d03.mp3", "This sample is a good example of a life story.": "audio/cau/c91d20f5c55e871f.mp3", "What do you say when you meet someone?": "audio/cau/ebd766cb7a0b37c7.mp3", "Say hello! Mi said hello to everyone.": "audio/cau/835b6b164eec79c4.mp3", "What is the artisan saying about his work?": "audio/cau/758a63f41cdaea82.mp3", "Grandpa said an old saying about hard work.": "audio/cau/dae1465b6bed02a4.mp3", "I go to school by bike.": "audio/cau/df5dcef1ab40916f.mp3", "I put my books in my schoolbag before school.": "audio/cau/c492164eb59da7f4.mp3", "My schoolbag is too heavy today.": "audio/cau/8d0a65c64cf8ce99.mp3", "She puts her books in her schoolbag.": "audio/cau/3f97f32ee71ad86a.mp3", "You seem very tired today, Nam.": "audio/cau/35d0d317c3b0474d.mp3", "The test seems easy, but be careful.": "audio/cau/464d526b15ed996d.mp3", "Select the correct answer A, B or C.": "audio/cau/fa11d36a6784e8b9.mp3", "She selected a red dress for the party.": "audio/cau/949a496976983bca.mp3", "Write a sentence about your family.": "audio/cau/9ffdb94eb27ae024.mp3", "This sentence is short and easy to read.": "audio/cau/f99b7a9b5f47ebe1.mp3", "Please write five sentences about your best friend.": "audio/cau/9fbb8a8d97d0001d.mp3", "The first sentence is easy, but the other sentences are hard.": "audio/cau/8cf810890ade1eda.mp3", "There's a shelf next to the bed.": "audio/cau/2ff12f0ee8c17812.mp3", "My books are on the shelf.": "audio/cau/85f866544d3e129e.mp3", "Let's go to the shop to buy a lamp.": "audio/cau/02d8310bb74af7bc.mp3", "There is a small shop near my house.": "audio/cau/e63a93ab9fc8033d.mp3", "He didn't make a single mistake in his talk.": "audio/cau/a286d003a6b3c6e9.mp3", "I have a single bed in my room.": "audio/cau/3b00e1fa6b523672.mp3", "The students came in singly.": "audio/cau/4d50a06594c554d1.mp3", "You can buy the eggs singly.": "audio/cau/e88d2514704395b1.mp3", "Sister is a singular noun.": "audio/cau/e25c86754cb67d1f.mp3", "We use 's after a singular noun.": "audio/cau/b7c2888d377657fe.mp3", "My sister is kind and very funny.": "audio/cau/682ebfe0aa138164.mp3", "I have one sister and two brothers.": "audio/cau/14c3dc4d63096025.mp3", "This is my sister's bike.": "audio/cau/756d8b1673625602.mp3", "My sisters' room is very tidy.": "audio/cau/ce72ae2163b2c5c1.mp3", "This is my sister's desk.": "audio/cau/555e6db76992fc2b.mp3", "My sister's room is next to mine.": "audio/cau/4cd932c57b2362e9.mp3", "My house is small but cosy.": "audio/cau/361843b6d8177bed.mp3", "I live in a small flat, not a big house.": "audio/cau/e341afdae498f225.mp3", "My cat sleeps on the sofa every afternoon.": "audio/cau/c5d52b7613fd47a8.mp3", "Can you speak English well?": "audio/cau/7e70c8ed41dd5f73.mp3", "Mi spoke to her teacher after class.": "audio/cau/9631c4f9d08103cf.mp3", "She is a good English speaker.": "audio/cau/ad8983e10a3153eb.mp3", "Turn up the speaker, please.": "audio/cau/176c25890d4baf0b.mp3", "Our head teacher gave a short speech today.": "audio/cau/d7f9999a0661fac2.mp3", "Mi will speak first, then Nam will give his speech.": "audio/cau/e7405c38166acf2a.mp3", "She spoke English very well.": "audio/cau/021d27ba9b445e58.mp3", "I spoke to my teacher after class.": "audio/cau/8a7ed13ad52bfd30.mp3", "Our English lesson will start at eight.": "audio/cau/920ac7d03b952080.mp3", "We start at seven and finish at eleven.": "audio/cau/f8b0988a876acebc.mp3", "Mi is a student at Ba Dinh Secondary School.": "audio/cau/569937b828afcac4.mp3", "Every student must study hard for the test.": "audio/cau/88443b78f0da0120.mp3", "Mi studies English every evening.": "audio/cau/b1218f9b9530760b.mp3", "Nam studied hard last year, and now he studies even harder.": "audio/cau/9817881934cebf3a.mp3", "I study English every evening.": "audio/cau/2a98035816ae0fe1.mp3", "Hoa is a studious student; she likes to study maths.": "audio/cau/81fcae64bc4c3e71.mp3", "Nguyen is a common surname in Viet Nam.": "audio/cau/c8102c73dadc352c.mp3", "What is your surname?": "audio/cau/67eafe2d8243a1d5.mp3", "In \"don't\", the letter t comes from not.": "audio/cau/549e7bc5a2456c75.mp3", "I didn't go out because I was tired.": "audio/cau/5cc7479c1b749e64.mp3", "Put your books on the table, please.": "audio/cau/467dab8d487aa55a.mp3", "Our timetable is a table of all our lessons.": "audio/cau/995dc4d40f2b5ff8.mp3", "I often talk to my grandma on the phone.": "audio/cau/30262ea1745db608.mp3", "Lan is talkative; she loves to talk and chat with friends.": "audio/cau/ef14453a567466fc.mp3", "My mum taught me how to cook.": "audio/cau/26258741e92965e1.mp3", "Mr Minh taught us English last year.": "audio/cau/c50edf18517998fc.mp3", "My mother will teach me how to cook.": "audio/cau/a219134d114e3ba6.mp3", "Mr Minh taught me English, and he is a great teacher.": "audio/cau/f4262b30c0d7e28d.mp3", "Our English teacher is very kind.": "audio/cau/4869000a32bce322.mp3", "Ms Hoa taught us maths last year; she is a great teacher.": "audio/cau/01cfa396481f53ff.mp3", "The teacher's desk is next to the board.": "audio/cau/117c585a8118e3fc.mp3", "Please put your books on the teacher's table.": "audio/cau/a102c5684f7ac5bc.mp3", "Ms Lan is teaching Class 6A now.": "audio/cau/acf50be4cb481bbc.mp3", "My aunt is a teacher; she loves teaching.": "audio/cau/8c228681a916a270.mp3", "They will televise the football match.": "audio/cau/fe8512575a4fbca8.mp3", "The festival is televised every year.": "audio/cau/9db88e86d5457ce7.mp3", "There is a television in the living room.": "audio/cau/b6e9f08b84a3491c.mp3", "My grandma watches television in the evening.": "audio/cau/405c173d0715402b.mp3", "I had breakfast, and then I went to school.": "audio/cau/e707895b95dcb0e6.mp3", "First, wash the rice. Next, cook it. Then, eat it.": "audio/cau/2bb6330c0be506ed.mp3", "There is a big garden in my house.": "audio/cau/94db3c106fafa1ac.mp3", "Your bag is here, and my bag is over there.": "audio/cau/37204e4c7e951d02.mp3", "The most important thing is to be honest.": "audio/cau/c302c847e8e66725.mp3", "Something is wrong; one thing is missing from my bag.": "audio/cau/c14d87bcc3d6fc9b.mp3", "I put my things in my schoolbag.": "audio/cau/bf35bafff88418e4.mp3", "There are many good things at my school, not just one thing.": "audio/cau/26ddc5ba45fd5524.mp3", "Let's look at our new timetable.": "audio/cau/b37160eda36c9395.mp3", "We have Maths on Monday according to the timetable.": "audio/cau/46e65b162f79e5db.mp3", "I totally agree with you.": "audio/cau/2ed025b410dc2507.mp3", "The town is totally different now; it changed completely.": "audio/cau/7c44b917714a1ef2.mp3", "Is it true that Nam can sing well?": "audio/cau/b793f0302657ab80.mp3", "The story is true, not false.": "audio/cau/fd6a61c02d4b7fe6.mp3", "I'm truly sorry.": "audio/cau/e7ae5dcb584f8045.mp3", "It was a truly beautiful day.": "audio/cau/b7c3ef82c1d2475c.mp3", "Please tell me the truth.": "audio/cau/09d3635c1d77c2fb.mp3", "He always tells the truth.": "audio/cau/1b99124c4acee059.mp3", "There is a big TV in our living room.": "audio/cau/12dac61f7442af7c.mp3", "Nam watches TV after dinner, and his television is new.": "audio/cau/f8c696f4133477c5.mp3", "My uncle lives in an apartment in Ho Chi Minh City.": "audio/cau/db1cb4b61c56f27b.mp3", "Uncle Hai has a big country house.": "audio/cau/20c31966a0349b2e.mp3", "That story is untrue.": "audio/cau/93e4988bfe2eafab.mp3", "Some news on the Internet is untrue.": "audio/cau/43deb053ae5f269d.mp3", "We use computers to make our visual story.": "audio/cau/1f9e65093a2c0cf1.mp3", "This app is very useful, and I use it every day.": "audio/cau/7434eb2ec1577d85.mp3", "This dictionary is very useful.": "audio/cau/d616d82dd437efdf.mp3", "A computer is useful, but a broken one is useless.": "audio/cau/061aada006d6e574.mp3", "Spend your free time usefully.": "audio/cau/a5f343473daf5755.mp3", "Old bottles can be used usefully as pots.": "audio/cau/f80325fc53a6f5a0.mp3", "We talked about the usefulness of the Internet.": "audio/cau/1fa0f0d5fcdf7de1.mp3", "The usefulness of this tool is clear.": "audio/cau/a1f35dfbac0c1e29.mp3", "This broken umbrella is useless.": "audio/cau/87f4d5c1e27eee06.mp3", "It's useless to cry now.": "audio/cau/d2efa23c3f23f8b7.mp3", "Facebook has millions of users.": "audio/cau/3955ede83592bd40.mp3", "Enter your user name here.": "audio/cau/8f967e17a7ac312d.mp3", "How about + V-ing? How about going to the park?": "audio/cau/4bd32e061c4f1188.mp3", "In the formula, V means a verb, like 'go' or 'play'.": "audio/cau/2a5961c55ebdeb37.mp3", "'Play' is a verb, but 'happy' is not.": "audio/cau/7cb0163f6a27d0af.mp3", "Underline the verb in each sentence.": "audio/cau/c45fa8ec83b8ba93.mp3", "Write the -ing form of these verbs.": "audio/cau/9a8d4d3f46f1577e.mp3", "'Run' and 'swim' are verbs; can you find one more verb?": "audio/cau/1cd8c87f9c695ab7.mp3", "My clothes are in the wardrobe.": "audio/cau/bc9ff776614feda0.mp3", "There is a lamp between the bed and the wardrobe.": "audio/cau/dc5f208db094f909.mp3", "Nam was at home yesterday.": "audio/cau/faca1649a4ef8a76.mp3", "I was tired, but my friends were happy.": "audio/cau/e3e7c2c50296c48e.mp3", "We watch TV after dinner.": "audio/cau/8b47f4f4b321b7f8.mp3", "Nam is watching a film; his new watch is on the table.": "audio/cau/850cc4ddfbc726bf.mp3", "Trang watches films at the cinema at weekends.": "audio/cau/58771fac6bb56dc4.mp3", "My brother likes to watch football, and he watches it every Sunday.": "audio/cau/b5419c83106d199e.mp3", "Lan sings very well.": "audio/cau/8d831f0b90fa91ed.mp3", "Nam plays football well, but Phong plays better.": "audio/cau/7c13b2c077241009.mp3", "They were in Ha Noi last year.": "audio/cau/a884324b521a97cd.mp3", "I was at school, and my parents were at work.": "audio/cau/d6c97d0e9f2b3c05.mp3", "Where do you live, Lan?": "audio/cau/0c6d7d3df1a25694.mp3", "Where is my schoolbag, Mum?": "audio/cau/57a3c3d221996a0d.mp3", "My parents work in a hospital in Ha Noi.": "audio/cau/4a34bda1f13dc400.mp3", "My uncle is a hard-working worker; he works every day.": "audio/cau/4fe31bc354d9e0c5.mp3", "The worker wears a helmet.": "audio/cau/9c235c7e97cd46ce.mp3", "Factory workers work long hours.": "audio/cau/dd3d0d4cd13eb0b4.mp3", "My mum is working in the garden now.": "audio/cau/0fc0a939dbaf61f1.mp3", "Dad works hard, and today he is working late.": "audio/cau/8fff1884b3def435.mp3", "Please write your name here.": "audio/cau/a728b2e865ff5c76.mp3", "Mi likes to write, and she wrote a story yesterday.": "audio/cau/a907f42938059961.mp3", "My aunt is a writer.": "audio/cau/0b898dc7eb5824c9.mp3", "Mi wants to be a writer because she loves to write stories.": "audio/cau/5ce118b1d0da266b.mp3", "She was writing a book when I phoned her.": "audio/cau/97a3ce971a3a7562.mp3", "Mi is writing a letter, and she wrote one yesterday too.": "audio/cau/f5189e5fac049044.mp3", "Lan's answer was wrong, so she tried again.": "audio/cau/1b25a01594f7e8c8.mp3", "You look sad, Minh. What's wrong?": "audio/cau/bde31146d26c8a31.mp3", "He spelled my name wrongly.": "audio/cau/6f375b9c1ad0fc97.mp3", "She was wrongly blamed for the mistake.": "audio/cau/5c429e62a8f6c2c9.mp3", "Lie becomes lying: change 'ie' to y and add -ing.": "audio/cau/ccd0d01ed2295121.mp3", "The word 'yellow' begins with the letter y.": "audio/cau/413244207833f8bd.mp3"};
